class basic_specs {
 private:
  enum : unsigned { /* bit masks & shifts as in file */ max_fill_size = 4 };
  unsigned data_ = 1 << fill_size_shift;
  static_assert(sizeof(basic_specs::data_) * CHAR_BIT >= 18, "");
  char fill_data_[max_fill_size] = {' '};
  FMT_CONSTEXPR void set_fill_size(size_t size) { /* ... */ }
 public:
  constexpr auto type() const -> presentation_type { return static_cast<presentation_type>(data_ & type_mask); }
  FMT_CONSTEXPR void set_type(presentation_type t) { /* ... */ }
  constexpr auto align() const -> align { return static_cast<fmt::align>((data_ & align_mask) >> align_shift); }
  FMT_CONSTEXPR void set_align(fmt::align a) { /* ... */ }
  constexpr auto dynamic_width() const -> arg_id_kind { /* ... */ }
  FMT_CONSTEXPR void set_dynamic_width(arg_id_kind w) { /* ... */ }
  FMT_CONSTEXPR auto dynamic_precision() const -> arg_id_kind { /* ... */ }
  FMT_CONSTEXPR void set_dynamic_precision(arg_id_kind p) { /* ... */ }
  constexpr auto dynamic() const -> bool { return (data_ & (width_mask | precision_mask)) != 0; }
  constexpr auto sign() const -> sign { return static_cast<fmt::sign>((data_ & sign_mask) >> sign_shift); }
  FMT_CONSTEXPR void set_sign(fmt::sign s) { /* ... */ }
  constexpr auto upper() const -> bool { return (data_ & uppercase_mask) != 0; }
  FMT_CONSTEXPR void set_upper() { data_ |= uppercase_mask; }
  constexpr auto alt() const -> bool { return (data_ & alternate_mask) != 0; }
  FMT_CONSTEXPR void set_alt() { data_ |= alternate_mask; }
  FMT_CONSTEXPR void clear_alt() { data_ &= ~alternate_mask; }
  constexpr auto localized() const -> bool { return (data_ & localized_mask) != 0; }
  FMT_CONSTEXPR void set_localized() { data_ |= localized_mask; }
  constexpr auto fill_size() const -> size_t { return (data_ & fill_size_mask) >> fill_size_shift; }
  template <typename Char, FMT_ENABLE_IF(std::is_same<Char, char>::value)>
  constexpr auto fill() const -> const Char* { return fill_data_; }
  template <typename Char, FMT_ENABLE_IF(!std::is_same<Char, char>::value)>
  constexpr auto fill() const -> const Char* { return nullptr; }
  template <typename Char> constexpr auto fill_unit() const -> Char { /* packs first up to 3 bytes */ }
  FMT_CONSTEXPR void set_fill(char c) { fill_data_[0] = c; set_fill_size(1); }
  template <typename Char>
  FMT_CONSTEXPR void set_fill(basic_string_view<Char> s) { /* multi-unit fill */ }
  FMT_CONSTEXPR void copy_fill_from(const basic_specs& specs) { /* ... */ }
};

