class fixed_buffer_traits {
 private:
  size_t count_ = 0;
  size_t limit_;
 public:
  constexpr explicit fixed_buffer_traits(size_t limit) : limit_(limit) {}
  constexpr auto count() const -> size_t { return count_; }
  FMT_CONSTEXPR auto limit(size_t size) -> size_t {
    size_t n = limit_ > count_ ? limit_ - count_ : 0;
    count_ += size;
    return min_of(size, n);
  }
};

template <typename Context> class basic_format_args {
 private:
  unsigned long long desc_;
  union { const detail::value<Context>* values_; const basic_format_arg<Context>* args_; };
  constexpr auto is_packed() const -> bool { return (desc_ & detail::is_unpacked_bit) == 0; }
  constexpr auto has_named_args() const -> bool { return (desc_ & detail::has_named_args_bit) != 0; }
  FMT_CONSTEXPR auto type(int index) const -> detail::type { /* extract packed type */ }
  template <int NUM_ARGS, int NUM_NAMED_ARGS, unsigned long long DESC>
  using store = detail::format_arg_store<Context, NUM_ARGS, NUM_NAMED_ARGS, DESC>;
 public:
  using format_arg = basic_format_arg<Context>;
  constexpr basic_format_args() : desc_(0), args_(nullptr) {}
  template <int NUM_ARGS, int NUM_NAMED_ARGS, unsigned long long DESC,
            FMT_ENABLE_IF(NUM_ARGS <= detail::max_packed_args)>
  constexpr FMT_ALWAYS_INLINE basic_format_args(const store<NUM_ARGS, NUM_NAMED_ARGS, DESC>& s)
      : desc_(DESC | (NUM_NAMED_ARGS != 0 ? +detail::has_named_args_bit : 0)), values_(s.args) {}
  template <int NUM_ARGS, int NUM_NAMED_ARGS, unsigned long long DESC,
            FMT_ENABLE_IF(NUM_ARGS > detail::max_packed_args)>
  constexpr basic_format_args(const store<NUM_ARGS, NUM_NAMED_ARGS, DESC>& s)
      : desc_(DESC | (NUM_NAMED_ARGS != 0 ? +detail::has_named_args_bit : 0)), args_(s.args) {}
  constexpr basic_format_args(const format_arg* args, int count, bool has_named = false)
      : desc_(detail::is_unpacked_bit | detail::to_unsigned(count) | (has_named ? +detail::has_named_args_bit : 0)), args_(args) {}
  FMT_CONSTEXPR auto get(int id) const -> format_arg { /* fetch by index */ }
  template <typename Char> auto get(basic_string_view<Char> name) const -> format_arg { int id = get_id(name); return id >= 0 ? get(id) : format_arg(); }
  template <typename Char> FMT_CONSTEXPR auto get_id(basic_string_view<Char> name) const -> int { /* lookup in named args */ }
  auto max_size() const -> int { /* compute based on desc_ */ }
};
using format_args = basic_format_args<context>;

